<script lang="ts">

  let { name = "flame", cls = "w-6 h-6", x = undefined, y = undefined, size = undefined, color = undefined, outline = undefined }: { name?: string; cls?: string; x?: number; y?: number; size?: number; color?: string; outline?: string } = $props();
  const glyph = $derived.by(() => {
    const found = GLYPHS[name];
    if (!found && typeof console !== 'undefined') console.warn(`[GameIcon] unknown glyph: ${name}`);
    return found ?? GLYPHS['flame'];
  });
  // Outline width in glyph-local units (~1 screen unit at typical map sizes).
  const outlineWidth = $derived(Number(glyph.vb.split(' ')[2] ?? 512) * 0.04);
</script>

